CREATE TABLE "Listing" ("id" TEXT NOT NULL,"slug" TEXT NOT NULL,"published" BOOLEAN NOT NULL DEFAULT false,"featured" BOOLEAN NOT NULL DEFAULT false,"data" JSONB NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Listing_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Listing_slug_key" ON "Listing"("slug");
CREATE TABLE "Lead" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"phone" TEXT NOT NULL,"enquiry" TEXT NOT NULL,"message" TEXT NOT NULL,"consent" BOOLEAN NOT NULL,"status" TEXT NOT NULL DEFAULT 'new',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Lead_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Image" ("id" TEXT NOT NULL,"mime" TEXT NOT NULL,"bytes" BYTEA NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Image_pkey" PRIMARY KEY ("id"));
CREATE TABLE "RateBucket" ("key" TEXT NOT NULL,"count" INTEGER NOT NULL DEFAULT 0,"expiresAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "RateBucket_pkey" PRIMARY KEY ("key"));
